import pandas as pd

def calculate_turn_scores(rolls):
    scores = {}

    # 1. High and Often: max(rolls) * rolls.count(max(rolls))
    max_val = max(rolls)
    scores['High and Often'] = max_val * rolls.count(max_val)

    # 2. Summation: sum(rolls)
    scores['Summation'] = sum(rolls)

    # 3. Highs and Lows: max(rolls) * min(rolls) * (max(rolls) - min(rolls))
    min_val = min(rolls)
    scores['Highs and Lows'] = max_val * min_val * (max_val - min_val)

    # 4. Only two numbers: 30 if len(set(rolls)) <= 2
    if len(set(rolls)) <= 2:
        scores['Only two numbers'] = 30
    else:
        scores['Only two numbers'] = 0

    # 5. All the numbers: 40 if set(rolls) == {1, 2, 3, 4, 5, 6}
    if set(rolls) == {1, 2, 3, 4, 5, 6}:
        scores['All the numbers'] = 40
    else:
        scores['All the numbers'] = 0

    # 6. Ordered subset of four: 50 if run of 4 consecutive
    found_run = False
    rolls_list = list(rolls)
    for i in range(3): # Start index 0, 1, 2
        subset = rolls_list[i:i+4]
        # Increasing
        if subset[1] == subset[0] + 1 and subset[2] == subset[1] + 1 and subset[3] == subset[2] + 1:
            found_run = True
            break
        # Decreasing
        if subset[1] == subset[0] - 1 and subset[2] == subset[1] - 1 and subset[3] == subset[2] - 1:
            found_run = True
            break
    if found_run:
        scores['Ordered subset of four'] = 50
    else:
        scores['Ordered subset of four'] = 0

    return scores

def solve():
    df = pd.read_excel('/root/data.xlsx', sheet_name='Data', header=None, skiprows=9)

    games = {}
    for index, row in df.iterrows():
        if pd.isna(row[2]) and pd.isna(row[3]):
            continue
        try:
            game_num = int(row[3])
            rolls = [int(row[i]) for i in range(4, 10)]
            if game_num not in games:
                games[game_num] = []
            games[game_num].append(rolls)
        except (ValueError, TypeError):
            continue

    game_scores = {}
    for game_num in sorted(games.keys()):
        turns = games[game_num]
        if len(turns) == 2:
            scores1 = calculate_turn_scores(turns[0])
            scores2 = calculate_turn_scores(turns[1])

            max_game_score = 0
            cats = list(scores1.keys())
            for cat1 in cats:
                for cat2 in cats:
                    if cat1 == cat2:
                        continue
                    score = scores1[cat1] + scores2[cat2]
                    if score > max_game_score:
                        max_game_score = score
            game_scores[game_num] = max_game_score
        elif len(turns) == 1:
            scores1 = calculate_turn_scores(turns[0])
            # Other turn is all zeros
            max_game_score = max(scores1.values())
            game_scores[game_num] = max_game_score
        else:
            game_scores[game_num] = 0

    p1_wins = 0
    p2_wins = 0

    # Matches: (1 vs 2), (3 vs 4), ...
    for m in range(1, 1501):
        g1 = 2*m - 1
        g2 = 2*m

        score1 = game_scores.get(g1, 0)
        score2 = game_scores.get(g2, 0)

        if score1 > score2:
            p1_wins += 1
        elif score2 > score1:
            p2_wins += 1

    print(p1_wins - p2_wins)

solve()

